window.docContents[96].resolve({"/releases/#release-v4___36___0":{"contents":"\n\n* Breaking change: Verso now uses the Lean types and custom HTML syntax provided by Lean, rather than its own implementation of a custom HTML syntax. (#974, #987)* Breaking change: Verso markup is parsed by code that is part of Lean.\nThe upstream parser was rewritten to enable code formatting, with substantial improvements to error messages along the way.\nAdapting to the new parser required changes in Verso. (#989)\n\n\n\n\n\n","context":"Writing Documentation in Lean with Verso\u0009Release Notes","header":"Verso 4.36.0 (in development)","id":"/releases/#release-v4___36___0"}});